import sys

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    if n <= 0 or len(data) < 1:
        return

    words = []
    for i in range(1, min(n + 1, len(data))):
        word = data[i]
        words.append(word)

    if not words:
        return

    max_length = max(len(word.rstrip()) for word in words)

    result = []
    for word in words:
        if len(word.rstrip()) == max_length:
            result.append(word.rstrip())

    for w in result:
        print(w)

if __name__ == "__main__":
    main()
